/**
 * assets.js — sprite cắt từ ảnh tham chiếu cyber-defense.png (data URL
 * WebP): 3 tháp field + 3 icon build bar, bot địch, lõi CORE, pad xây,
 * texture PCB nền. Mask mềm để sprite hòa vào nền bo mạch.
 */

export const ASSETS = {
  pcb:
    "data:image/webp;base64,",
  towerRapid:
    "data:image/webp;base64,",
  towerSlow:
    "data:image/webp;base64,",
  towerBlast:
    "data:image/webp;base64,",
  iconRapid:
    "data:image/webp;base64,",
  iconSlow:
    "data:image/webp;base64,",
  iconBlast:
    "data:image/webp;base64,",
  botBasic:
    "data:image/webp;base64,",
  botEye:
    "data:image/webp;base64,",
  botFast:
    "data:image/webp;base64,",
  core:
    "data:image/webp;base64,",
  pad:
    "data:image/webp;base64,",
};

/** Tạo và decode Image cho toàn bộ ASSETS; trả về map name → HTMLImageElement. */
export function loadImages() {
  const out = {};
  for (const [k, v] of Object.entries(ASSETS)) {
    const im = new Image();
    im.decoding = "async";
    im.src = v;
    out[k] = im;
  }
  return out;
}

/** Ảnh đã sẵn sàng vẽ chưa (decode xong, hợp lệ). */
export const ready = (im) => !!(im && im.complete && im.naturalWidth > 0);
